{
  "packet_id": "H6-T01-1",
  "claim_id": "C014",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C014.component",
    "value": "Comparable equipment and crew groups should be compared before their observations are pooled.",
    "scope": "The proposed analysis; the criteria for group comparability are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P010",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P010 directly states the comparison-before-pooling requirement without specifying comparability criteria."
    }
  },
  "signal_basis": {
    "component_id": "C014.signal_basis",
    "value": "Comparable turnaround observations are summarized using late-start rates, delay minutes and stage-specific counts, and examined for recurring delays and temporal changes. Changing job mix, workload and measurement practices can create or conceal patterns.",
    "scope": "The proposed daily review and weekly summaries across equipment and crew groups, before pooling.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P010",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply comparable recording, the review schedule and measures, temporal signals and sources of misleading patterns; P010 identifies the grouping and pooling context."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C014.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported procedural safeguard."
    }
  },
  "rationale": "Pooling can conceal differences between groups or make changes in group composition appear to be temporal changes. Comparing comparable groups first is therefore warranted as a safeguard for interpreting the described sequence. The claim does not assert that pooling is ultimately justified or that the comparison establishes causation.",
  "uncertainty": "Comparability criteria remain unspecified, limiting how the safeguard is implemented without undermining the bounded recommendation.",
  "anomalies": []
}
